package cn.courselens;

import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.os.*;import java.io.*;

public final class AiScreenService extends Service {
 static volatile boolean active,morrowVisible;static volatile long capturedAt;private static volatile byte[] latest;private MediaProjection projection;private VirtualDisplay display;private ImageReader reader;private HandlerThread captureThread;private long lastCapture;
 static byte[] frame(){return active?latest:null;}
 @Override public IBinder onBind(Intent intent){return null;}
 @Override public int onStartCommand(Intent intent,int flags,int startId){
  if(intent==null||"stop".equals(intent.getAction())){stopSelf();return START_NOT_STICKY;}if(active)return START_NOT_STICKY;latest=null;capturedAt=0;
  NotificationManager manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("ai-screen","AI 屏幕共享",NotificationManager.IMPORTANCE_LOW));PendingIntent stop=PendingIntent.getService(this,0,new Intent(this,AiScreenService.class).setAction("stop"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).setAction(MainActivity.OPEN_TAB).putExtra("primaryTab",3).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notification=new Notification.Builder(this,"ai-screen").setSmallIcon(R.drawable.ic_chat).setContentTitle("AI 屏幕共享已开启").setContentText("暂存最近画面，发送消息时供 AI 查看；点停止结束").setOngoing(true).setContentIntent(open).addAction(new Notification.Action.Builder(null,"停止共享",stop).build()).build();if(Build.VERSION.SDK_INT>=29)startForeground(731,notification,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);else startForeground(731,notification);
  try{Intent consent=Build.VERSION.SDK_INT>=33?intent.getParcelableExtra("consent",Intent.class):intent.getParcelableExtra("consent");if(consent==null)throw new IllegalArgumentException();projection=getSystemService(MediaProjectionManager.class).getMediaProjection(Activity.RESULT_OK,consent);if(projection==null)throw new IllegalStateException();projection.registerCallback(new MediaProjection.Callback(){@Override public void onStop(){stopSelf();}},new Handler(Looper.getMainLooper()));android.util.DisplayMetrics metrics=new android.util.DisplayMetrics();getSystemService(android.view.WindowManager.class).getDefaultDisplay().getRealMetrics(metrics);float scale=Math.min(1f,1280f/Math.max(metrics.widthPixels,metrics.heightPixels));int width=Math.max(1,Math.round(metrics.widthPixels*scale)),height=Math.max(1,Math.round(metrics.heightPixels*scale));reader=ImageReader.newInstance(width,height,PixelFormat.RGBA_8888,2);captureThread=new HandlerThread("ai-screen-frame");captureThread.start();reader.setOnImageAvailableListener(source->{try(Image image=source.acquireLatestImage()){if(image==null||morrowVisible||SystemClock.elapsedRealtime()-lastCapture<1500)return;lastCapture=SystemClock.elapsedRealtime();Image.Plane plane=image.getPlanes()[0];int stride=plane.getPixelStride(),padded=plane.getRowStride()/stride;Bitmap bitmap=Bitmap.createBitmap(padded,image.getHeight(),Bitmap.Config.ARGB_8888);Bitmap crop=null;try{bitmap.copyPixelsFromBuffer(plane.getBuffer());crop=Bitmap.createBitmap(bitmap,0,0,image.getWidth(),image.getHeight());ByteArrayOutputStream jpeg=new ByteArrayOutputStream();crop.compress(Bitmap.CompressFormat.JPEG,80,jpeg);if(active&&!morrowVisible){latest=jpeg.toByteArray();capturedAt=System.currentTimeMillis();}}finally{if(crop!=null&&crop!=bitmap)crop.recycle();bitmap.recycle();}}catch(RuntimeException ignored){}},new Handler(captureThread.getLooper()));active=true;display=projection.createVirtualDisplay("Morrow AI shared screen",width,height,metrics.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,null);}catch(RuntimeException e){stopSelf();}return START_NOT_STICKY;
 }
 @Override public void onTaskRemoved(Intent rootIntent){stopSelf();}
 @Override public void onDestroy(){active=false;latest=null;capturedAt=0;if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null)projection.stop();if(captureThread!=null)captureThread.quitSafely();stopForeground(true);super.onDestroy();}
}
